msg.query = `MATCH (n) DETACH DELETE n`
msg.database = "memgraph"
return msg;

// 1. Get and parse the data from the Read File node
let data = msg.payload;

// Convert Buffer to string if necessary
if (Buffer.isBuffer(data)) {
    data = data.toString('utf8');
}

// Parse string to JSON object if necessary
if (typeof data === 'string') {
    try {
        data = JSON.parse(data);
    } catch (e) {
        node.error("Failed to parse JSON. Ensure the file is valid JSON.", msg);
        return null;
    }
}

// Verify it's an array
if (!Array.isArray(data)) {
    node.error("Expected the JSON to be an array of objects.", msg);
    return null;
}

const queryParts = [];

// 2. Generate Nodes
queryParts.push("  // Creazione dei nodi");
data.forEach(row => {
    if (row.node_var) {
        queryParts.push(`  (${row.node_var}:Place {department: '${row.department}', room: '${row.room_name}'})`);
    }
});

// 3. Generate Relationships
data.forEach(row => {
    const targets = row.connected_to;

    // Check if targets exist and is an array with at least one element
    if (Array.isArray(targets) && targets.length > 0) {
        // Format the comment to show targets in uppercase
        const commentTargets = targets.map(t => t.toUpperCase()).join(', ');
        queryParts.push(`\n  // ${row.room_name} -> [${commentTargets}]`);

        targets.forEach(t => {
            queryParts.push(`  (${row.node_var})-[:CONNECTED_TO]->(${t})`);
        });
    }
});

// 4. Build the final query string with correct comma/semicolon placement
let finalQuery = "CREATE\n";

for (let i = 0; i < queryParts.length; i++) {
    const part = queryParts[i];

    // Determine if this is the last actual Cypher command (ignoring comments)
    let isLastStatement = true;
    for (let j = i + 1; j < queryParts.length; j++) {
        if (!queryParts[j].trim().startsWith("//")) {
            isLastStatement = false;
            break;
        }
    }

    if (part.trim().startsWith("//")) {
        // It's a comment, just add a newline
        finalQuery += part + "\n";
    } else {
        // It's a statement, append a comma or semicolon
        finalQuery += part;
        if (!isLastStatement) {
            finalQuery += ",\n";
        } else {
            finalQuery += ";\n";
        }
    }
}

// 5. Output the formatted Cypher query
msg.query = finalQuery;
return msg;

let cachingData = {};
let device_id = msg.payload.device_id;

cachingData.device_id = device_id;
// We assign the sensors object, keeping in mind JS objects are passed by reference
cachingData.sensors = msg.payload.sensors;

// Retrieve global settings from the context (fallback to an empty object if not found)
let global_settings = global.get("global_settings") || {};
let excluded_sensors = global_settings.excluded_sensors || [];

// Dynamically delete sensors based on the YAML configuration
if (cachingData.sensors) {
    for (let i = 0; i < excluded_sensors.length; i++) {
        let sensorToRemove = excluded_sensors[i];

        // Check if the sensor exists before attempting to delete it
        if (cachingData.sensors.hasOwnProperty(sensorToRemove)) {
            delete cachingData.sensors[sensorToRemove];
        }
    }
}

return cachingData;

msg.topic = msg.payload.room

msg.payload = [
    "danger_" + msg.payload.danger_type, msg.payload.danger
]

return msg;

// 1. Fetch maps from the global context (populated by the YAML loader)
let roomToDepartment = global.get("roomToDepartment") || {};
let sensorToRoom = global.get("sensorToRoom") || {};

let sensor = msg.device_id;

// 2. Ensure the incoming message actually has a device_id
if (!sensor) {
    node.warn("Missing msg.device_id. Cannot map room.");
    return null; // Halts the flow for this message
}

let room = sensorToRoom[sensor];

// 3. Ensure the sensor is actually mapped to a room
if (!room) {
    node.warn(`No room mapping found for sensor ID: ${sensor}`);
    return null;
}

// 4. Get department, providing a fallback if the room isn't categorized
let department = roomToDepartment[room] || "UnknownDepartment";

// 5. Attach the mapped values to the message object
msg.room = room;
msg.department = department;

return msg;

let sensor_keys = Object.keys(msg.payload)

msg.current_data = msg.payload
msg.payload = sensor_keys
msg.sensor_attributes = sensor_keys

return msg;

function strict_comparison(value1, value2){
    return value1 !== value2
}


let attributes_to_update = {}

for (let i = 0; i<msg.payload.length;i++ ){
    let key = msg.sensor_attributes[i]
    let cache = msg.payload[i]
    let current = msg.current_data[key]

    let to_update = strict_comparison(cache, current)
    if (to_update){
        attributes_to_update[key] = current
    }
}
msg.attributes_to_update = attributes_to_update
msg.current_data= null
msg.payload=null
return msg;

// 1. Define threshold evaluation strategies
// Each function returns true if the value should be updated, false otherwise.
const thresholdStrategies = {
    percentage: function(newValue, oldValue, threshold) {
        if (oldValue === 0) return newValue !== 0;
        let percentageChange = Math.abs(newValue - oldValue) / Math.abs(oldValue);
        return percentageChange >= threshold;
    },
    absolute: function(newValue, oldValue, threshold) {
        let diff = Math.abs(newValue - oldValue);
        return diff >= threshold;
    },
    always: function(newValue, oldValue, threshold) {
        return newValue !== oldValue; // Updates whenever it's not strictly equal
    }
    // Add new strategies here in the future (e.g., 'moving_average', 'time_based')
};

// 2. Fetch configurations from global context
let sensor_parameters = global.get("sensor_parameters") || global.get("sensor_configs") || {};

// 3. Fallback if the cache is completely empty
if (!msg.cached_snapshot || Object.keys(msg.cached_snapshot).length === 0) {
    msg.attributes_to_update = msg.current_data;
    return msg;
}

let attributes_to_update = {};

// 4. Compare current data against the cached snapshot
for (const [key, value] of Object.entries(msg.current_data)) {
    let old_value = msg.cached_snapshot[key];

    // If the sensor is entirely new to the cache, force an update
    if (old_value === undefined) {
        attributes_to_update[key] = value;
        continue;
    }

    // Handle numeric values using the dynamic strategies
    if (typeof value === 'number' && typeof old_value === 'number') {

        let sensorConfig = sensor_parameters[key] || {};
        let thresholdType = sensorConfig.threshold_type || "percentage";
        let thresholdValue = (sensorConfig.threshold_value !== undefined) ? sensorConfig.threshold_value : 0.05;

        // Select the evaluation function, fallback to 'percentage' if the type is unrecognized
        let evaluateThreshold = thresholdStrategies[thresholdType] || thresholdStrategies["percentage"];

        // Execute the strategy
        if (evaluateThreshold(value, old_value, thresholdValue)) {
            attributes_to_update[key] = value;
        }

    } 
    // Handle non-numeric values (e.g., strings, booleans)
    else if (old_value !== value) {
        attributes_to_update[key] = value;
    }
}

// 5. Prepare the output message
msg.attributes_to_update = attributes_to_update;

// Clean up memory payload
msg.current_data = null;
msg.cached_snapshot = null;

return msg;

msg.payload = msg.sensors
msg.topic = msg.department + ":" + msg.room
return msg;

// Retrieve the previously saved global settings, with a fallback to an empty object
let global_settings = global.get("global_settings") || {};

// Get ttl_seconds from the YAML file; if it doesn't exist or isn't loaded yet, use 300 as the default (5 minutes)
let ttl = global_settings.ttl_seconds || 300; 

// Format the message for the Lua/Redis node
msg.payload = [msg.topic, ttl, ...msg.sensor_attributes];

return msg;

// Retrieve the danger tiers from the global context.
// If it hasn't been loaded yet, fall back to the default values.
const dangerTiers = global.get("danger_tiers") || {
    'high': 1,
    'medium': 2,
    'low': 3
};

// Default to tier 3 (lowest priority)
let tier = 3;

if (msg.danger !== undefined) {
    let dangerLevel = msg.danger.toLowerCase();

    // Assign the tier based on the YAML mapping.
    // If the danger level isn't found in the mapping, it defaults to 3.
    tier = dangerTiers[dangerLevel] || 3;
}

// Calculate priority based on the tier and the current timestamp
let priority = parseFloat(`${tier}.${Date.now()}`);

// Format the payload for the Redis Priority Queue (ZADD command)
msg.payload = ["room_pq", priority, msg.topic];

msg.topic = null;
return msg;

// 1. Write the query using placeholders (names starting with $)
msg.query = `
  MATCH (n:Place {department: $department, room: $room})
  SET n += $sensors
  RETURN n;
`;

// 2. Pass the actual parameters in msg.params
// (The database will automatically map $room to params.room)
msg.params = {
    department: msg.department,
    room: msg.room,
    sensors: msg.attributes_to_update
};

msg.database = "memgraph";

msg.payload = null
return msg;

if (msg.payload) {
    // 1. Save aggregation configurations (used by the aggregator node)
    if (msg.payload.sensor_configs) {
        global.set('sensor_configs', msg.payload.sensor_configs);
    }

    // 2. Save global settings (thresholds, ttl, excluded sensors)
    if (msg.payload.global_settings) {
        global.set('global_settings', msg.payload.global_settings);
    }

    // 3. Save danger tiers
    if (msg.payload.danger_tiers) {
        global.set('danger_tiers', msg.payload.danger_tiers);
    }

    // 4. Save departments and create reverse maps for sensor mapping
    if (msg.payload.departments) {
        global.set('departments', msg.payload.departments);

        let roomMap = {};
        let sensorMap = {};

        // Loop through the structure to create O(1) fast-read dictionaries
        for (const [deptName, rooms] of Object.entries(msg.payload.departments)) {
            for (const roomObj of rooms) {
                // Map Room -> Department
                roomMap[roomObj.name] = deptName;

                // Map Sensor -> Room
                if (Array.isArray(roomObj.sensors)) {
                    for (const sensor of roomObj.sensors) {
                        sensorMap[sensor] = roomObj.name;
                    }
                }
            }
        }

        // Save the maps ready for the "mapping department" node
        global.set('roomToDepartment', roomMap);
        global.set('sensorToRoom', sensorMap);
    }

    node.warn("YAML configurations loaded and saved in the global context.");
}

return msg;

let topic = (msg.topic !== undefined && msg.topic !== null) ? msg.topic.toString() : "";
if (!topic) return null;

let redisKey = `room:${topic}`;

// Retrieve the parameters from the global context 
// (Ensure the string matches the key saved in the previous node, e.g., "sensor_configs")
let sensor_parameters = global.get("sensor_configs") || {};

if (msg.payload && typeof msg.payload === 'object' && !Array.isArray(msg.payload)) {

    // 1. Register the room as active in Redis if it isn't already
    context.get("active_rooms", "redis", function (err, rooms) {
        rooms = rooms || {};
        if (!rooms[topic]) {
            rooms[topic] = true;
            context.set("active_rooms", rooms, "redis", function (err) {
                if (err) node.error(err);
            });
        }
    });

    // 2. Retrieve current room data and append the new sensor payloads
    context.get(redisKey, "redis", function (err, roomData) {
        roomData = roomData || {};
        let now = Date.now();

        Object.keys(msg.payload).forEach(sensorKey => {
            let val = parseFloat(msg.payload[sensorKey]);

            if (!isNaN(val)) {
                if (!roomData[sensorKey]) {
                    // Apply the bucket_ms from the YAML parameters, fallback to 60000ms (1 minute)
                    let bucket = (sensor_parameters[sensorKey] && sensor_parameters[sensorKey].bucket_ms)
                        ? parseInt(sensor_parameters[sensorKey].bucket_ms)
                        : 60000;

                    roomData[sensorKey] = { payloads: [], next_send: now + bucket };
                }

                roomData[sensorKey].payloads.push(val);
            }
        });

        // 3. Save the updated payloads back to Redis
        context.set(redisKey, roomData, "redis", function (err) {
            if (err) node.error(err);
        });
    });
}

return null;

